
-- ASHA AI SYNTHETIC DEMO DATASET
-- ALL RECORDS ARE SYNTHETIC. NOT LIVE HOSPITAL DATA. NOT FOR REAL PATIENT CARE.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS asha_resource_events (
    record_id TEXT PRIMARY KEY,
    data_label TEXT NOT NULL CHECK (data_label = 'SYNTHETIC_DEMO_NOT_REAL'),
    event_timestamp_utc TEXT NOT NULL,
    reported_timestamp_utc TEXT NOT NULL,
    district TEXT NOT NULL,
    hospital_id TEXT NOT NULL CHECK (hospital_id LIKE 'LHN-TN-%'),
    latitude_demo_only REAL NOT NULL CHECK (latitude_demo_only BETWEEN 8.0 AND 13.5),
    longitude_demo_only REAL NOT NULL CHECK (longitude_demo_only BETWEEN 76.0 AND 80.5),
    total_beds INTEGER NOT NULL CHECK (total_beds >= 1),
    occupied_beds INTEGER NOT NULL CHECK (occupied_beds BETWEEN 0 AND total_beds),
    available_beds INTEGER NOT NULL CHECK (available_beds = total_beds - occupied_beds),
    total_icu_beds INTEGER NOT NULL CHECK (total_icu_beds >= 1),
    occupied_icu_beds INTEGER NOT NULL CHECK (occupied_icu_beds BETWEEN 0 AND total_icu_beds),
    available_icu_beds INTEGER NOT NULL CHECK (available_icu_beds = total_icu_beds - occupied_icu_beds),
    doctors_on_duty INTEGER NOT NULL CHECK (doctors_on_duty >= 0),
    doctors_required_estimate INTEGER NOT NULL CHECK (doctors_required_estimate >= 0),
    ventilators_total INTEGER NOT NULL CHECK (ventilators_total >= 0),
    ventilators_available INTEGER NOT NULL CHECK (ventilators_available BETWEEN 0 AND ventilators_total),
    oxygen_capacity_l_demo_only INTEGER NOT NULL CHECK (oxygen_capacity_l_demo_only >= 0),
    oxygen_level_pct INTEGER NOT NULL CHECK (oxygen_level_pct BETWEEN 0 AND 100),
    blood_group TEXT NOT NULL CHECK (blood_group IN ('O+','O-','A+','A-','B+','B-','AB+','AB-')),
    blood_units_demo_only INTEGER NOT NULL CHECK (blood_units_demo_only >= 0),
    ambulances_total INTEGER NOT NULL CHECK (ambulances_total >= 0),
    ambulances_available INTEGER NOT NULL CHECK (ambulances_available BETWEEN 0 AND ambulances_total),
    ambulance_status_sample TEXT NOT NULL,
    emergency_type TEXT NOT NULL,
    urgency_1_to_5 INTEGER NOT NULL CHECK (urgency_1_to_5 BETWEEN 1 AND 5),
    patients_waiting_demo_only INTEGER NOT NULL CHECK (patients_waiting_demo_only >= 0),
    source_type TEXT NOT NULL,
    data_age_minutes INTEGER NOT NULL CHECK (data_age_minutes >= 0),
    missing_field_injected TEXT NOT NULL,
    sensor_conflict_flag INTEGER NOT NULL CHECK (sensor_conflict_flag IN (0,1)),
    verification_status TEXT NOT NULL CHECK (verification_status IN ('verified','needs_review','conflict_detected','stale_data','missing_data')),
    resource_pressure_count INTEGER NOT NULL CHECK (resource_pressure_count BETWEEN 0 AND 7),
    prototype_recommendation TEXT NOT NULL,
    human_review_required INTEGER NOT NULL CHECK (human_review_required = 1),
    clinical_decision_use TEXT NOT NULL CHECK (clinical_decision_use = 'NOT_FOR_REAL_PATIENT_CARE'),
    ml_split TEXT NOT NULL CHECK (ml_split IN ('train','test'))
);

CREATE INDEX IF NOT EXISTS idx_asha_timestamp ON asha_resource_events(event_timestamp_utc);
CREATE INDEX IF NOT EXISTS idx_asha_district ON asha_resource_events(district);
CREATE INDEX IF NOT EXISTS idx_asha_hospital ON asha_resource_events(hospital_id);
CREATE INDEX IF NOT EXISTS idx_asha_verification ON asha_resource_events(verification_status);
CREATE INDEX IF NOT EXISTS idx_asha_emergency ON asha_resource_events(emergency_type);


